// #0f04ee (עבר QA 26.10): /orders на телефоне 360/375/390/414 — ряд вкладок «הכל / ממתינות לאישור / אושרו / נדחו» без
//   прокрутки вбок, каждая вкладка и её число целиком внутри ряда и экрана; так же при «כל החודשים» (самые длинные числа).
//   Способ программиста (gap 16 ниже 640px, перенос последней вкладки на 2-ю строку) — не требование; проверяется результат.
//   ≥ 640 (1024 с меню, 1440) — без изменений: один ряд, gap 24px. Клик по вкладке → aria-current и список этой вкладки
//   («מציג … מתוך N» = число на вкладке). Тот же фикс в ряду вкладок /catalog («הכל · זמינים · לא זמינים») — регресс 360 и 1440.
// Только чтение (фильтр месяца — в конце возвращается текущий) → @prod-safe.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const ORDER_TABS = [/^הכל\d+$/, /^ממתינות לאישור\d+$/, /^אושרו\d+$/, /^נדחו\d+$/];
const CATALOG_TABS = [/^הכל\d+$/, /^זמינים\d+$/, /^לא זמינים\d+$/];
const month = (page: Page) => page.getByRole('combobox', { name: 'סינון לפי חודש' });
const tab = (page: Page, name: string) => page.locator('button[aria-current]').filter({ hasText: new RegExp(`^${name}\\d+$`) });
const shown = (page: Page) => page.getByText(/^מציג \d+–\d+ מתוך \d+ תוצאות$/);

/** Замер ряда вкладок (родитель кнопок с aria-current, первая — «הכל»). */
const measureTabs = (page: Page) => page.evaluate(() => {
  const first = [...document.querySelectorAll('button[aria-current]')].find((e) => /^הכל/.test(e.textContent!.trim()))!;
  const row = first.parentElement!;
  const bx = (e: Element) => { const b = e.getBoundingClientRect(); return { l: b.left, t: b.top, r: b.right, b: b.bottom }; };
  const tabs = [...row.querySelectorAll(':scope > button')].map((b) => {
    const num = [...b.querySelectorAll('span')].find((s) => /^\d+$/.test(s.textContent!.trim()));
    return { text: b.textContent!.trim(), box: bx(b), num: num ? bx(num) : null, numClip: num ? num.scrollWidth > num.clientWidth + 1 : true, current: b.getAttribute('aria-current') };
  });
  return { vw: innerWidth, docSW: document.documentElement.scrollWidth, rowSW: row.scrollWidth, rowCW: row.clientWidth, row: bx(row), gap: getComputedStyle(row).columnGap, tabs };
});

type Tabs = Awaited<ReturnType<typeof measureTabs>>;
const inside = (a: { l: number; r: number }, c: { l: number; r: number }) => a.l >= c.l - 0.5 && a.r <= c.r + 0.5;

function expectTabsFit(m: Tabs, names: RegExp[], tag: string) {
  expect(m.tabs.map((t) => t.text), `${tag}: вкладки с числами`).toHaveLength(names.length);
  m.tabs.forEach((t, i) => expect(t.text, `${tag}: вкладка ${i + 1}`).toMatch(names[i]));
  expect(m.docSW, `${tag}: страница без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
  expect(m.rowSW, `${tag}: ряд вкладок без прокрутки вбок`).toBeLessThanOrEqual(m.rowCW + 1);
  const screen = { l: 0, r: m.vw };
  for (const t of m.tabs) {
    expect(inside(t.box, m.row) && inside(t.box, screen), `${tag}: «${t.text}» целиком в ряду и в экране`).toBe(true);
    expect(t.num, `${tag}: у «${t.text}» есть число`).not.toBeNull();
    expect(inside(t.num!, m.row) && inside(t.num!, screen), `${tag}: число «${t.text}» в ряду и в экране`).toBe(true);
    expect(t.numClip, `${tag}: число «${t.text}» не обрезано`).toBe(false);
  }
  // RTL: первая вкладка («הכל») — крайняя справа
  expect(m.tabs[0].box.r, `${tag}: «הכל» справа`).toBeGreaterThanOrEqual(Math.max(...m.tabs.map((t) => t.box.r)) - 0.5);
}

async function openOrders(page: Page) {
  await page.goto('/orders');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
  await expect(tab(page, 'הכל')).toBeVisible({ timeout: 30_000 });
  const initial = await month(page).inputValue();
  return initial;
}

/** «כל החודשים» и ждём, пока список и число «הכל» обновятся (N на вкладке = «מתוך N»). */
async function allMonths(page: Page) {
  await month(page).selectOption({ label: 'כל החודשים' });
  await expect.poll(async () => {
    const t = (await tab(page, 'הכל').innerText()).replace(/\D/g, '');
    const s = await shown(page).innerText().catch(() => '');
    return s.endsWith(`מתוך ${t} תוצאות`);
  }, { timeout: 20_000 }).toBe(true);
}

async function restoreMonth(page: Page, initial: string) {
  await month(page).selectOption(initial);
  await expect(month(page), 'фильтр месяца возвращён').toHaveValue(initial);
}

test.describe('orders — לשוניות «הזמנות» בטלפון בלי גלילה לרוחב, כל המספרים נראים (#0f04ee)', () => {
  test('360/375/390/414: 4 הלשוניות והמספרים בתוך השורה והמסך — החודש הנוכחי ו«כל החודשים» #0f04ee @iphone @orders @prod-safe', async ({ page }) => {
    test.setTimeout(120_000);
    await page.setViewportSize({ width: 360, height: 740 });
    const initial = await openOrders(page);
    for (const [w, h] of [[360, 740], [375, 812], [390, 844], [414, 896]] as const) {
      await page.setViewportSize({ width: w, height: h });
      await expect.poll(() => page.evaluate(() => innerWidth)).toBe(w);
      expectTabsFit(await measureTabs(page), ORDER_TABS, `${w}, месяц ${initial}`);
    }
    await allMonths(page);
    for (const [w, h] of [[360, 740], [375, 812], [390, 844], [414, 896]] as const) {
      await page.setViewportSize({ width: w, height: h });
      await expect.poll(() => page.evaluate(() => innerWidth)).toBe(w);
      expectTabsFit(await measureTabs(page), ORDER_TABS, `${w}, כל החודשים`);
    }
    await restoreMonth(page, initial);
  });

  test('360, «כל החודשים»: לחיצה על «נדחו» — aria-current והרשימה של הלשונית; חזרה ל«הכל» #0f04ee @iphone @orders @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    await page.setViewportSize({ width: 360, height: 740 });
    const initial = await openOrders(page);
    await allMonths(page);
    const n = (await tab(page, 'נדחו').innerText()).replace(/\D/g, '');
    await tab(page, 'נדחו').click();
    await expect(tab(page, 'נדחו')).toHaveAttribute('aria-current', 'true');
    for (const other of ['הכל', 'ממתינות לאישור', 'אושרו']) await expect(tab(page, other)).toHaveAttribute('aria-current', 'false');
    await expect(shown(page), 'список вкладки «נדחו»: N = число на вкладке').toHaveText(new RegExp(`מתוך ${n} תוצאות$`), { timeout: 20_000 });
    await expect(page.getByRole('button', { name: /^#\d+ / }).first(), 'первая карточка — «נדחתה»').toContainText('נדחתה');
    expectTabsFit(await measureTabs(page), ORDER_TABS, '360 после клика «נדחו»');
    const all = (await tab(page, 'הכל').innerText()).replace(/\D/g, '');
    await tab(page, 'הכל').click();
    await expect(tab(page, 'הכל')).toHaveAttribute('aria-current', 'true');
    await expect(shown(page)).toHaveText(new RegExp(`מתוך ${all} תוצאות$`), { timeout: 20_000 });
    await restoreMonth(page, initial);
  });

  test('1024 (תפריט צד) ו-1440: שורה אחת, gap 24px, בלי גלילה לרוחב (ללא שינוי) #0f04ee @desktop @orders @prod-safe', async ({ page }) => {
    test.setTimeout(90_000);
    await page.setViewportSize({ width: 1440, height: 900 });
    const initial = await openOrders(page);
    await allMonths(page);
    for (const [w, h] of [[1024, 768], [1440, 900]] as const) {
      await page.setViewportSize({ width: w, height: h });
      await expect.poll(() => page.evaluate(() => innerWidth)).toBe(w);
      const m = await measureTabs(page);
      expectTabsFit(m, ORDER_TABS, `${w}`);
      expect(m.gap, `${w}: gap между вкладками`).toBe('24px');
      const tops = m.tabs.map((t) => t.box.t);
      expect(Math.max(...tops) - Math.min(...tops), `${w}: все вкладки в одном ряду`).toBeLessThanOrEqual(1);
    }
    await restoreMonth(page, initial);
  });
});

test.describe('catalog — לשוניות «הכל · זמינים · לא זמינים» במלואן (#0f04ee, אותו תיקון)', () => {
  async function checkCatalog(page: Page, w: number, h: number) {
    await page.setViewportSize({ width: w, height: h });
    await page.goto('/catalog');
    await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
    for (const n of ['הכל', 'זמינים', 'לא זמינים']) await expect(tab(page, n), `«${n}» с числом`).toBeVisible({ timeout: 30_000 });
    const m = await measureTabs(page);
    expectTabsFit(m, CATALOG_TABS, `/catalog ${w}`);
    return m;
  }

  test('/catalog 360: שלוש הלשוניות והמספרים בתוך השורה והמסך #0f04ee @iphone @catalog @prod-safe', async ({ page }) => {
    test.setTimeout(60_000);
    await checkCatalog(page, 360, 740);
  });

  test('/catalog 1440: שלוש הלשוניות בשורה אחת, gap 24px #0f04ee @desktop @catalog @prod-safe', async ({ page }) => {
    test.setTimeout(60_000);
    const m = await checkCatalog(page, 1440, 900);
    expect(m.gap, '1440: gap').toBe('24px');
    const tops = m.tabs.map((t) => t.box.t);
    expect(Math.max(...tops) - Math.min(...tops), '1440: один ряд').toBeLessThanOrEqual(1);
  });
});
